def transform(grid):
    """Replicate a color strip alongside a straight 5-colored divider."""
    h, w = len(grid), len(grid[0])
    src = [row[:] for row in grid]
    out = [row[:] for row in grid]

    # A vertical 5-divider: the colored strip attached to its lower end is
    # repeated upward, keeping its columns immediately to the right of the wall.
    for c in range(w):
        r = 0
        while r < h:
            if src[r][c] != 5 or (r > 0 and src[r - 1][c] == 5):
                r += 1
                continue
            end = r
            while end + 1 < h and src[end + 1][c] == 5:
                end += 1
            if c + 1 < w:
                # Seed consists of the consecutive colored rows to the right
                # that touch the bottom of the divider.
                seed_end = end
                if any(src[seed_end][x] != 0 for x in range(c + 1, w)):
                    seed_start = seed_end
                    while seed_start > r and any(src[seed_start - 1][x] != 0 for x in range(c + 1, w)):
                        seed_start -= 1
                    tile = [src[y][c + 1:] for y in range(seed_start, seed_end + 1)]
                    width = max((x - c for y in range(seed_start, seed_end + 1) for x in range(c + 1, w) if src[y][x] != 0), default=0)
                    if tile and width:
                        for y in range(r, end + 1):
                            rowpat = tile[(y - r) % len(tile)]
                            for dx in range(1, width + 1):
                                if out[y][c + dx] == 0:
                                    out[y][c + dx] = rowpat[dx - 1]
            r = end + 1

    # A horizontal 5-divider: a vertical strip attached below its left end is
    # repeated across the divider's columns.
    for r in range(h):
        c = 0
        while c < w:
            if src[r][c] != 5 or (c > 0 and src[r][c - 1] == 5):
                c += 1
                continue
            end = c
            while end + 1 < w and src[r][end + 1] == 5:
                end += 1
            if end > c and r + 1 < h:
                seed = []
                y = r + 1
                while y < h and src[y][c] != 0:
                    seed.append(src[y][c])
                    y += 1
                if seed:
                    for x in range(c, end + 1):
                        for dy, value in enumerate(seed, start=1):
                            if r + dy < h and out[r + dy][x] == 0:
                                out[r + dy][x] = value
            c = end + 1
    return out
